from fastapi import APIRouter, FastAPI, FastAPIError
import pytest

def test_circular_router():
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as e:
        assert str(e) == "A router cannot be included within itself."
        print("Caught expected FastAPIError")
        return
    except Exception as e:
        pytest.fail(f"Caught unexpected exception: {type(e).__name__}: {e}")

    pytest.fail("Did not raise FastAPIError when including router within itself")

if __name__ == "__main__":
    try:
        test_circular_router()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        exit(1)
